// Local contracts from RoomRoutes.ts and HistoryRoutes.ts. No upstream calls.
const http = require('http');
const namespace = 'syncbeatsNativeHome';
const artwork=["data:image/jpeg;base64,","data:image/jpeg;base64,","data:image/jpeg;base64,"];
const songs = [
  {url:'https://www.youtube.com/watch?v=A1b2C3d4E5f',title:'A Walk',uploaderName:'Tycho',duration:218,thumbnail:null},
  {url:'https://www.youtube.com/watch?v=B2c3D4e5F6g',title:'Kerala',uploaderName:'Bonobo',duration:237,thumbnail:null},
  {url:'https://www.youtube.com/watch?v=C3d4E5f6G7h',title:'Tadow',uploaderName:'Masego',duration:302,thumbnail:null}
];
songs.forEach((song,i)=>song.thumbnail='http://127.0.0.1:5277/syncbeats-native-room-home/art/'+i);
const item = (song,index) => ({id:'track-'+index,trackUrl:'youtube:'+new URL(song.url).searchParams.get('v'),title:song.title,artist:song.uploaderName,durationSec:song.duration,thumbnail:song.thumbnail,queueIndex:index,isCurrent:index===0});
http.createServer(async (req,res) => {
  const url = new URL(req.url,'http://localhost');
  if(url.pathname.startsWith('/art/')){const art=artwork[Number(url.pathname.split('/').at(-1))];if(!art){res.writeHead(404);return res.end()}res.writeHead(200,{'Content-Type':art.slice(5,art.indexOf(';'))});return res.end(Buffer.from(art.split(',')[1],'base64'))}
  const reply=(status,body)=>{res.writeHead(status,{'Content-Type':'application/json'});res.end(JSON.stringify(body))};
  const calls=await pm.state.get(namespace+'.calls')||[];
  calls.push({method:req.method,path:url.pathname,query:Object.fromEntries(url.searchParams),body:req.body,authorization:req.headers.authorization,device:req.headers['x-device-id']});
  await pm.state.set(namespace+'.calls',calls);
  if(url.pathname==='/__calls')return reply(200,calls.slice(0,-1));
  if(url.pathname==='/video-identity')return reply(200,{title:'The Weeknd - Blinding Lights (Official Video)',author_name:'TheWeekndVEVO'});
  if(url.pathname==='/cover-search' && req.method==='GET') {
    const term=url.searchParams.get('term')||'';
    if(term.includes('Unavailable'))return reply(503,{error:'Unavailable'});
    if(term.includes('Malformed'))return reply(200,{results:[{trackName:123}]});
    const base='http://127.0.0.1:5277/syncbeats-native-room-home';
    if(term.includes('Missing'))return reply(200,{results:[]});
    return reply(200,{results:[
      {trackName:'Blinding Lights',artistName:'Unrelated Artist',collectionName:'Unrelated album',artworkUrl100:base+'/art/0'},
      {trackName:'Blinding Lights (Live)',artistName:'The Weeknd',collectionName:'Live At SoFi Stadium',artworkUrl100:base+'/art/0'},
      {trackName:'Blinding Lights',artistName:'The Weeknd',collectionName:'Blinding Lights - Single',artworkUrl100:base+'/art/0'},
      {trackName:'Blinding Lights',artistName:'The Weeknd',collectionName:'After Hours',artworkUrl100:base+'/art/1'}
    ]});
  }
  if(req.headers.authorization!=='Bearer native-home-test')return reply(401,{error:'Invalid token'});
  if(req.headers['x-device-id']==='fault-server')return reply(503,{error:'Music discovery is temporarily unavailable'});
  if(req.headers['x-device-id']==='fault-malformed')return reply(200,[{}]);
  const artist = {id:'anirudh',name:'Anirudh Ravichander',languages:['Telugu','Tamil'],genres:['Film music']};
  const freshTaste = () => ({onboardingStatus:'NEW',languages:[],genres:[],favoriteArtistIds:[],customArtists:[],useActivity:false});
  if(url.pathname==='/recommendations/catalog'&&req.method==='GET')return reply(200,{languages:['Telugu','Tamil','English'],genres:['Film music','Pop'],artists:[artist]});
  if(url.pathname==='/recommendations/profile'&&req.method==='PUT'){
    await pm.state.set(namespace+'.taste',req.body);return reply(200,req.body);
  }
  if(url.pathname==='/recommendations/profile'&&req.method==='DELETE'){
    await pm.state.set(namespace+'.taste',freshTaste());return reply(200,{ok:true});
  }
  if(url.pathname==='/recommendations/events'&&req.method==='POST'){
    if(!req.body?.eventId||req.body.artistId!==artist.id)return reply(400,{error:'Choose valid feedback'});
    return reply(200,{ok:true});
  }
  if(url.pathname==='/recommendations/feed'&&req.method==='GET'){
    const profile=await pm.state.get(namespace+'.taste')||freshTaste();
    return reply(200,{modelVersion:'rules-v1',profile,sections:[{id:'discover',title:profile.onboardingStatus==='NEW'?'Starter picks':'Discover from your interests',picks:[{...artist,query:artist.name+' songs',reason:'A starter pick from SyncBeats',score:0}]}]});
  }
  if(/^\/rooms\/[0-9]{6}\/youtube-search$/.test(url.pathname)&&req.method==='GET') {
    if(!url.searchParams.get('q'))return reply(400,{error:'Query is required'});
    return reply(200,songs);
  }
  if(url.pathname==='/history/recent'&&req.method==='GET') {
    if(url.searchParams.get('userId')!=='native-home-user')return reply(400,{error:'userId is required'});
    return reply(200,{listens:[{youtubeId:'A1b2C3d4E5f',title:'A Walk',artist:'Tycho',thumbnail:null},{youtubeId:'A1b2C3d4E5f',title:'A Walk',artist:'Tycho',thumbnail:null},{youtubeId:'invalid/id',title:'Invalid source',artist:null,thumbnail:null}],searches:[]});
  }
  let queue=await pm.state.get(namespace+'.queue')||songs.map(item);
  if(/^\/rooms\/[0-9]{6}\/queue\/reorder$/.test(url.pathname)&&req.method==='PUT') {
    const {itemId,newIndex}=req.body||{};
    if(!itemId||typeof newIndex!=='number'||!Number.isInteger(newIndex))return reply(400,{error:"We couldn't work out where to move that track."});
    const index=queue.findIndex(x=>x.id===itemId);
    if(index<0)return reply(404,{error:'That track is no longer in the queue'});
    queue.splice(newIndex,0,queue.splice(index,1)[0]);
    await pm.state.set(namespace+'.queue',queue);
    return reply(200,{ok:true,queue});
  }
  if(/^\/rooms\/[0-9]{6}\/enqueue-youtube$/.test(url.pathname)&&req.method==='POST') {
    const {youtubeUrl,title}=req.body||{};
    if(!youtubeUrl||!title)return reply(400,{error:'youtubeUrl and title are required'});
    const youtubeId=new URL(youtubeUrl).searchParams.get('v');
    let match=queue.find(x=>x.trackUrl==='youtube:'+youtubeId),duplicate=!!match;
    if(!match){match=item({url:youtubeUrl,title,uploaderName:'YouTube',duration:null,thumbnail:null},queue.length);queue.push(match);await pm.state.set(namespace+'.queue',queue)}
    return reply(201,{item:match,queued:!duplicate,duplicate});
  }
  reply(501,{error:'Endpoint not modeled by native home verification'});
}).listen(process.env.PORT);
